cells={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
# candidate tiles square 2x2 and L tetromino? L triominoes
squares=[]
for r in range(4):
 for c in range(6):
  s={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
  if s<=cells: squares.append(s)
Ls=[]
# all 2x2 blocks with one cell omitted
for r in range(4):
 for c in range(6):
  b={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
  for omit in b:
   t=b-{omit}
   if t<=cells: Ls.append(t)
# likely actually L triomino = 3 cells in 2x2
sol=[]
def rec(rem,chosen, sqcount):
 if not rem:
  if sqcount==1: sol.append(chosen)
  return
 x=min(rem)
 for t in Ls+squares:
  if x in t and t<=rem:
   rec(rem-t,chosen+[t],sqcount+(t in squares))
rec(cells,[],0)
len(sol), squares, sol[:3]
